// Demo.js
import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Demo.css';

// FontAwesome imports
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faGithub } from '@fortawesome/free-brands-svg-icons';
import { faUpRightFromSquare, faBars, faTimes, faArrowDown, faPlus } from '@fortawesome/free-solid-svg-icons';
import { faFile, faPenToSquare } from '@fortawesome/free-regular-svg-icons';
import { faStar as farStar } from '@fortawesome/free-regular-svg-icons';

function Demo() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // 1) Create a ref for our <video> element
  const videoRef = useRef(null);

  // 2) Use useEffect to set playback speed once the component mounts
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.playbackRate = 10; // 2x speed
    }
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen((prev) => !prev);
  };

  return (
    <div className="Demo">
      {/* NAVIGATION BAR */}
      <nav className="navbar">
        <div className="navbar-logo">
          <img src="logo192.png" alt="AskNAU logo" />
          <span>AskNAU</span>
        </div>

        {/* Mobile menu icon */}
        <button className="menu-icon" onClick={toggleMenu}>
          <FontAwesomeIcon icon={isMenuOpen ? faTimes : faBars} />
        </button>

        {/* Menu links */}
        <ul className={`navbar-links ${isMenuOpen ? 'open' : ''}`}>
          <li>
            <a
              href="https://github.com/zkalykov/asknau"
              target="_blank"
              rel="noopener noreferrer"
            >
              <FontAwesomeIcon icon={faGithub} style={{ marginRight: '5px' }} />
              Github
            </a>
          </li>
          <li>
            <Link className="try-now" to="/chat">
              <FontAwesomeIcon icon={faUpRightFromSquare} style={{ marginRight: '10px' }} />
              Try Now
            </Link>
          </li>
        </ul>
      </nav>

      {/* HEADINGS */}
      <h1 className="first-word">First ever AI assistant for NAU students</h1>
      <h1 className="second-word">Meet AskNAU</h1>

      {/* CALL TO ACTION */}
      <center>
        <Link className="click-here" to="/chat">
          <FontAwesomeIcon icon={faUpRightFromSquare} style={{ marginRight: '10px' }} />
          Click here to start
        </Link>
      </center>

      {/* DEMO VIDEO SECTION */}
      <div className="demo-content">
        <video
          // 3) Attach the ref to the <video> element
          ref={videoRef}
          src="/demo_asknau.mov"
          autoPlay
          loop
          muted
          playsInline
          style={{ width: '100%', height: 'auto' }}
        />
      </div>

      {/* FEATURES SECTION */}
      <div className="can-do">
        <div className="feature">
          <h3>
            <FontAwesomeIcon icon={faFile} style={{ marginRight: '10px' }} />
            Courses
          </h3>
          <p>AskNAU can provide information about courses and their prerequisites.</p>
        </div>

        <div className="feature">
          <h3>
            <FontAwesomeIcon icon={farStar} style={{ marginRight: '10px' }} />
            Grades
          </h3>
          <p>By simply uploading your transcript, you can see your GPA or get help with it.</p>
        </div>

        <div className="feature">
          <h3>
            <FontAwesomeIcon icon={faPenToSquare} style={{ marginRight: '10px' }} />
            Plan
          </h3>
          <p>You can plan your career or see what classes you can take next semester.</p>
        </div>
      </div>

      {/* DEMO VIDEO / EXAMPLE SECTION */}
      <h1 className="first-word" style={{ paddingBottom: '20px' }}>
        <FontAwesomeIcon icon={faArrowDown} style={{ marginRight: '10px' }} />
        Example - Watch Demo (will be replaced)
      </h1>

      <div className="youtube-video-wrapper">
        <iframe
          className="youtube-video"
          src="https://www.youtube.com/embed/HK6y8DAPN_0"
          title="YouTube video player"
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
          width="100%"
        />
      </div>

      {/* READ MORE SECTION */}
      <h1 className="first-word">
        <FontAwesomeIcon icon={faPlus} style={{ marginRight: '10px' }} />
        Read More
      </h1>
      <div className="how-works">
        <h3>Project idea</h3>
        <p>Will be written soon</p>
      </div>

      {/* FOOTER */}
      <div className="footer">
        © AskNAU. All rights reserved.
      </div>
    </div>
  );
}

export default Demo;
